/**
 * OpenRouter Free Model Integration for OpenCode
 *
 * Dynamically discovers, caches, and connects to free AI models
 * via the OpenRouter API — zero hardcoded model lists.
 */

import { OpenRouterFree } from './src/index.js';

export { OpenRouterFree };
export type { Model, ChatMessage, ProviderResult, HealthResult, Capabilities } from './src/types.js';

# Programmatic API Usage

This skill provides a programmatic API for integrating free models into other tools.

## TypeScript Interface

```typescript
import { OpenRouterFree } from './index.js';

const orf = new OpenRouterFree();
await orf.init();

// List free coding models
const codingModels = orf.listFree({ hasTools: true });

// Get best model by context length
const best = orf.router.selectBest(orf.models);

// Send a message with automatic fallback
const { result, decision } = await orf.router.sendWithFallback(
  orf.listFree(),
  [{ role: 'user', content: 'Hello!' }],
);

// Health check all models
const health = await orf.checkHealth();
```

## Environment Variables

| Variable | Default | Description |
|----------|---------|-------------|
| `OPENROUTER_API_KEY` | — | API key for OpenRouter (required) |
| `OPENROUTER_BASE_URL` | `https://openrouter.ai/api/v1` | Custom API endpoint |
| `CACHE_TTL_MS` | `3600000` | Cache TTL in milliseconds |
| `OPENROUTER_MAX_DISPLAY` | `30` | Max models to display in CLI |

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { AliasManager } from './alias-manager.js';

const MODELS = [
  { id: 'deepseek/deepseek-r1-0528:free' },
  { id: 'qwen/qwen3-32b:free' },
  { id: 'google/gemma-3-27b-it:free' },
  { id: 'meta-llama/llama-3.1-8b-instruct:free' },
  { id: 'mistralai/mistral-small-3.1-24b-instruct:free' },
  { id: 'microsoft/phi-4-mini-instruct:free' },
  { id: 'openai/gpt-4o:free' },
];

describe('AliasManager', () => {
  it('resolves built-in aliases', () => {
    const mgr = new AliasManager();
    assert.equal(mgr.resolve('r1'), 'deepseek/deepseek-r1-0528:free');
    assert.equal(mgr.resolve('qwen'), 'qwen/qwen3-32b:free');
    assert.equal(mgr.resolve('unknown'), null);
  });

  it('resolve is case-insensitive', () => {
    const mgr = new AliasManager();
    assert.equal(mgr.resolve('R1'), 'deepseek/deepseek-r1-0528:free');
  });

  it('isAlias works', () => {
    const mgr = new AliasManager();
    assert.ok(mgr.isAlias('r1'));
    assert.ok(!mgr.isAlias('nonexistent'));
  });

  it('add creates new alias', () => {
    const mgr = new AliasManager();
    mgr.add('custom', 'custom/model:free');
    assert.equal(mgr.resolve('custom'), 'custom/model:free');
  });

  it('list returns copy', () => {
    const mgr = new AliasManager();
    const list = mgr.list();
    list.delete('r1');
    // Original not affected
    assert.ok(mgr.isAlias('r1'));
  });

  describe('expandSelector', () => {
    it('returns openrouter/free for best-free', () => {
      const mgr = new AliasManager();
      assert.equal(mgr.expandSelector('best-free', MODELS), 'openrouter/free');
    });

    it('returns :free suffixed selectors as-is', () => {
      const mgr = new AliasManager();
      assert.equal(mgr.expandSelector('custom/model:free', MODELS), 'custom/model:free');
    });

    it('finds exact model ID match', () => {
      const mgr = new AliasManager();
      assert.equal(mgr.expandSelector('openai/gpt-4o:free', MODELS), 'openai/gpt-4o:free');
    });

    it('resolves alias', () => {
      const mgr = new AliasManager();
      assert.equal(mgr.expandSelector('r1', MODELS), 'deepseek/deepseek-r1-0528:free');
    });

    it('fuzzy match on unique substring', () => {
      const mgr = new AliasManager();
      // "gpt-4o" only appears in one model
      assert.equal(mgr.expandSelector('gpt-4o', MODELS), 'openai/gpt-4o:free');
    });

    it('returns null for ambiguous prefix', () => {
      const mgr = new AliasManager();
      // Multiple models contain common substrings
      assert.equal(mgr.expandSelector('free', MODELS), 'openrouter/free'); // alias takes precedence
    });

    it('returns null for no match', () => {
      const mgr = new AliasManager();
      assert.equal(mgr.expandSelector('nonexistent-xyz', MODELS), null);
    });
  });

  describe('validateAgainst', () => {
    it('removes stale aliases', () => {
      const mgr = new AliasManager();
      const stale = mgr.validateAgainst(MODELS);
      // r1 target exists in MODELS, qwen target exists, etc.
      // But some built-in targets might not be in our test MODELS
      assert.ok(Array.isArray(stale));
    });

    it('keeps aliases whose targets exist', () => {
      const mgr = new AliasManager();
      mgr.validateAgainst(MODELS);
      assert.ok(mgr.isAlias('r1')); // target is in MODELS
      assert.ok(mgr.isAlias('free')); // openrouter/free always valid
    });

    it('removes aliases whose targets are gone', () => {
      const mgr = new AliasManager();
      mgr.add('gone', 'removed/model:free');
      const stale = mgr.validateAgainst(MODELS);
      assert.ok(stale.includes('gone'));
      assert.ok(!mgr.isAlias('gone'));
    });
  });
});

import { describe, it, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, rmSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import { CacheManager } from './cache-manager.js';
import type { Model } from './types.js';

function makeModel(id: string): Model {
  return {
    id,
    name: id,
    description: '',
    contextLength: 4096,
    pricing: { prompt: '0', completion: '0' },
    supportedParameters: [],
    defaultParameters: {},
    architecture: {},
    topProvider: {},
    outputModalities: ['text'],
    canonicalSlug: id,
    createdAt: null,
    expirationDate: null,
    perRequestLimits: null,
  };
}

describe('CacheManager', () => {
  let tmpDir: string;

  beforeEach(() => {
    tmpDir = mkdtempSync(join(tmpdir(), 'or-cache-test-'));
  });

  afterEach(() => {
    rmSync(tmpDir, { recursive: true, force: true });
  });

  it('returns null when no cache exists', () => {
    const cache = new CacheManager(tmpDir);
    assert.equal(cache.load(), null);
  });

  it('round-trips save/load', () => {
    const cache = new CacheManager(tmpDir);
    const models = [makeModel('test/model:free')];
    cache.save(models);

    const loaded = cache.load();
    assert.ok(loaded);
    assert.equal(loaded.length, 1);
    assert.equal(loaded[0].id, 'test/model:free');
  });

  it('returns null after TTL expires', () => {
    const cache = new CacheManager(tmpDir, 1); // 1ms TTL
    cache.save([makeModel('test:free')]);

    // Wait for TTL to expire
    const start = Date.now();
    while (Date.now() - start < 5) {} // busy-wait 5ms

    assert.equal(cache.load(), null);
  });

  it('returns null after invalidate', () => {
    const cache = new CacheManager(tmpDir);
    cache.save([makeModel('test:free')]);
    cache.invalidate();
    assert.equal(cache.load(), null);
  });

  it('getPath returns expected path', () => {
    const cache = new CacheManager(tmpDir);
    assert.ok(cache.getPath().includes('openrouter-model-cache.json'));
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { CapabilityDetector } from './capability-detector.js';

describe('CapabilityDetector', () => {
  describe('detect', () => {
    it('detects vision from supported params', () => {
      const caps = CapabilityDetector.detect(['vision', 'tools']);
      assert.ok(caps.vision);
      assert.ok(caps.toolCalling);
    });

    it('detects image-input as vision', () => {
      const caps = CapabilityDetector.detect(['image-input']);
      assert.ok(caps.vision);
    });

    it('detects structured outputs', () => {
      const caps = CapabilityDetector.detect(['structured_outputs']);
      assert.ok(caps.structuredOutputs);
    });

    it('detects json_mode as structured outputs', () => {
      const caps = CapabilityDetector.detect(['json_mode']);
      assert.ok(caps.structuredOutputs);
    });

    it('detects reasoning', () => {
      const caps = CapabilityDetector.detect(['reasoning']);
      assert.ok(caps.reasoning);
    });

    it('detects include_reasoning as reasoning', () => {
      const caps = CapabilityDetector.detect(['include_reasoning']);
      assert.ok(caps.reasoning);
    });

    it('streaming true when stream param present', () => {
      const caps = CapabilityDetector.detect(['stream']);
      assert.ok(caps.streaming);
    });

    it('streaming true when no params (unknown model)', () => {
      const caps = CapabilityDetector.detect([]);
      assert.ok(caps.streaming);
    });

    it('streaming false when params exist but no stream', () => {
      const caps = CapabilityDetector.detect(['tools', 'vision']);
      assert.ok(!caps.streaming);
    });

    it('codeGeneration always true', () => {
      const caps = CapabilityDetector.detect([]);
      assert.ok(caps.codeGeneration);
    });

    it('is case-insensitive', () => {
      const caps = CapabilityDetector.detect(['Vision', 'TOOLS']);
      assert.ok(caps.vision);
      assert.ok(caps.toolCalling);
    });

    it('returns all false for unrecognized params (except streaming/code)', () => {
      const caps = CapabilityDetector.detect(['unknown_param']);
      assert.ok(!caps.vision);
      assert.ok(!caps.toolCalling);
      assert.ok(!caps.structuredOutputs);
      assert.ok(!caps.reasoning);
      assert.ok(!caps.functionCalling);
      assert.ok(!caps.streaming);
      assert.ok(caps.codeGeneration);
    });
  });

  describe('summary', () => {
    it('lists capabilities as emoji tags', () => {
      const caps = CapabilityDetector.detect(['vision', 'tools', 'reasoning']);
      const s = CapabilityDetector.summary(caps);
      assert.ok(s.includes('vision'));
      assert.ok(s.includes('tool-calling'));
      assert.ok(s.includes('reasoning'));
    });

    it('returns text-only for no caps', () => {
      const caps = CapabilityDetector.detect([]);
      const s = CapabilityDetector.summary(caps);
      assert.equal(s, '📝 text-only');
    });
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { FallbackRouter } from './fallback-router.js';
import { ProviderAdapter } from './provider-adapter.js';
import { HealthChecker } from './health-checker.js';
import { ConfigLoader } from './config-loader.js';
import type { Model } from './types.js';

function makeModel(id: string, ctx: number, params: string[] = []): Model {
  return {
    id,
    name: id,
    description: '',
    contextLength: ctx,
    pricing: { prompt: '0', completion: '0' },
    supportedParameters: params,
    defaultParameters: {},
    architecture: {},
    topProvider: {},
    outputModalities: ['text'],
    canonicalSlug: id,
    createdAt: null,
    expirationDate: null,
    perRequestLimits: null,
  };
}

describe('FallbackRouter', () => {
  const config = new ConfigLoader();
  const provider = new ProviderAdapter(config);
  const health = new HealthChecker(config);
  const router = new FallbackRouter(provider, health, config);

  const models: Model[] = [
    makeModel('a/small:free', 4096),
    makeModel('b/big:free', 128000, ['tools', 'vision']),
    makeModel('c/medium:free', 32000, ['tools']),
    makeModel('d/paid', 200000, ['tools', 'vision']),
  ];

  describe('selectBest', () => {
    it('returns highest context free model', () => {
      const best = router.selectBest(models);
      assert.ok(best);
      assert.equal(best.id, 'b/big:free');
    });

    it('filters by requirements', () => {
      const best = router.selectBest(models, { vision: true });
      assert.ok(best);
      assert.equal(best.id, 'b/big:free');
    });

    it('returns null if no free model matches requirements', () => {
      const best = router.selectBest(models, { reasoning: true });
      assert.equal(best, null);
    });

    it('ignores paid models', () => {
      const best = router.selectBest(models);
      assert.ok(best);
      assert.notEqual(best.id, 'd/paid');
    });

    it('returns null for empty list', () => {
      assert.equal(router.selectBest([]), null);
    });
  });

  describe('selectFastest', () => {
    it('picks lowest latency healthy model', () => {
      const results = [
        { modelId: 'a', status: 'healthy', latencyMs: 500 },
        { modelId: 'b', status: 'healthy', latencyMs: 100 },
        { modelId: 'c', status: 'degraded', latencyMs: 50 },
      ];
      assert.equal(router.selectFastest(results), 'b');
    });

    it('returns null when all unhealthy', () => {
      const results = [
        { modelId: 'a', status: 'unavailable', latencyMs: null },
        { modelId: 'b', status: 'degraded', latencyMs: 200 },
      ];
      assert.equal(router.selectFastest(results), null);
    });

    it('returns null for empty results', () => {
      assert.equal(router.selectFastest([]), null);
    });
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { HealthChecker } from './health-checker.js';
import { ConfigLoader } from './config-loader.js';

describe('HealthChecker', () => {
  it('returns unavailable when no API key', async () => {
    const origKey = process.env.OPENROUTER_API_KEY;
    delete process.env.OPENROUTER_API_KEY;

    const config = new ConfigLoader();
    const checker = new HealthChecker(config);
    const result = await checker.ping('test/model:free');

    assert.equal(result.status, 'unavailable');
    assert.equal(result.error, 'No API key');
    assert.equal(result.modelId, 'test/model:free');

    if (origKey) process.env.OPENROUTER_API_KEY = origKey;
  });

  describe('checkMany', () => {
    it('returns results for all models (no key = all unavailable)', async () => {
      const origKey = process.env.OPENROUTER_API_KEY;
      delete process.env.OPENROUTER_API_KEY;

      const config = new ConfigLoader();
      const checker = new HealthChecker(config);
      const models = [
        { id: 'a:free', name: 'A', description: '', contextLength: 4096, pricing: { prompt: '0', completion: '0' }, supportedParameters: [], defaultParameters: {}, architecture: {}, topProvider: {}, outputModalities: ['text'], canonicalSlug: 'a:free', createdAt: null, expirationDate: null, perRequestLimits: null },
        { id: 'b:free', name: 'B', description: '', contextLength: 4096, pricing: { prompt: '0', completion: '0' }, supportedParameters: [], defaultParameters: {}, architecture: {}, topProvider: {}, outputModalities: ['text'], canonicalSlug: 'b:free', createdAt: null, expirationDate: null, perRequestLimits: null },
      ];

      const results = await checker.checkMany(models);
      assert.equal(results.length, 2);
      assert.equal(results[0].modelId, 'a:free');
      assert.equal(results[1].modelId, 'b:free');
      assert.ok(results.every((r) => r.status === 'unavailable'));

      if (origKey) process.env.OPENROUTER_API_KEY = origKey;
    });
  });
});

/**
 * Provider Adapter — sends chat completions through OpenRouter
 * with retry, fallback, and streaming support.
 */

import type { ChatMessage, ChatCompletion, ProviderResult } from './types.js';
import { ConfigLoader } from './config-loader.js';

export class ProviderAdapter {
  private config: ConfigLoader;

  constructor(config: ConfigLoader) {
    this.config = config;
  }

  /** Send a chat completion request. */
  async complete(opts: {
    model: string;
    messages: ChatMessage[];
    maxTokens?: number;
    temperature?: number;
    stream?: boolean;
    tools?: any[];
    toolChoice?: string;
    retries?: number;
  }): Promise<ProviderResult> {
    const apiKey = [REDACTED];
    if (!apiKey) {
      throw new Error('OPENROUTER_API_KEY not configured. Set it with: export OPENROUTER_API_KEY="your_key"');
    }

    const body: Record<string, any> = {
      model: opts.model,
      messages: opts.messages,
      stream: opts.stream ?? false,
      max_tokens: opts.maxTokens ?? 2048,
      temperature: opts.temperature ?? 0.7,
    };

    if (opts.tools?.length) body.tools = opts.tools;
    if (opts.toolChoice) body.tool_choice = opts.toolChoice;

    const maxRetries = opts.retries ?? 2;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        const resp = await fetch(`${this.config.getBaseUrl()}/chat/completions`, {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${apiKey}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(body),
          signal: AbortSignal.timeout(30_000),
        });

        if (resp.ok) {
          if (opts.stream) {
            return this.handleStream(resp, opts.model);
          }
          const data: ChatCompletion = (await resp.json()) as ChatCompletion;
          return {
            model: data.model ?? opts.model,
            choices: (data.choices ?? []).map((c) => ({
              index: c.index,
              message: {
                role: c.message?.role ?? 'assistant',
                content: c.message?.content ?? null,
              },
            })),
            usage: data.usage ?? null,
          };
        }

        if (resp.status === 429) {
          await this.sleep(1000 * (attempt + 1));
          continue;
        }
        if (resp.status >= 500) {
          await this.sleep(1000 * (attempt + 1));
          continue;
        }
        if (resp.status === 401) {
          throw new Error('Authentication failed — check your OPENROUTER_API_KEY.');
        }
        if (resp.status === 402) {
          throw new Error('Payment required — insufficient credits.');
        }

        const errBody = await resp.text();
        throw new Error(`Request failed (${resp.status}): ${errBody}`);
      } catch (err: any) {
        if (err.name === 'AbortError') {
          throw new Error('Request timed out.');
        }
        if (!err.message?.includes('retrying')) throw err;
      }
    }

    throw new Error('Request failed after retries.');
  }

  /** Handle streaming SSE responses. */
  private async handleStream(
    resp: Response,
    model: string,
  ): Promise<ProviderResult> {
    const reader = resp.body?.getReader();
    if (!reader) throw new Error('No response body for streaming.');

    const choices: Array<{ index: number; message: { role: string; content: string } }> = [
      { index: 0, message: { role: 'assistant', content: '' } },
    ];

    const decoder = new TextDecoder();
    let buffer = '';
    let lastUsage: { prompt_tokens: number; completion_tokens: number; total_tokens: number } | null = null;

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });

      const lines = buffer.split('\n');
      buffer = lines.pop() ?? '';

      for (const line of lines) {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith(':')) continue;
        if (trimmed === 'data: [DONE]') continue;
        if (!trimmed.startsWith('data: ')) continue;

        const payload = trimmed.slice(6).trim();
        if (!payload || payload === '[DONE]') continue;

        try {
          const chunk = JSON.parse(payload);
          const delta = chunk.choices?.[0]?.delta?.content;
          if (delta) {
            choices[0].message.content += delta;
          }
          if (chunk.usage) {
            lastUsage = chunk.usage;
          }
        } catch {
          // Skip malformed JSON chunks
        }
      }
    }

    return {
      model,
      choices,
      usage: lastUsage,
      streamed: true,
    };
  }

  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

/**
 * OpenRouter Free Model Integration for OpenCode
 *
 * Dynamically discovers, caches, and connects to free AI models
 * via the OpenRouter API — zero hardcoded model lists.
 */

import { ModelRegistry } from './model-registry.js';
import { CacheManager } from './cache-manager.js';
import { ConfigLoader } from './config-loader.js';
import { CapabilityDetector } from './capability-detector.js';
import { HealthChecker } from './health-checker.js';
import { ProviderAdapter } from './provider-adapter.js';
import { FallbackRouter } from './fallback-router.js';
import { AliasManager } from './alias-manager.js';
import type { Model, ChatMessage, ProviderResult, HealthResult, Capabilities } from './types.js';

export class OpenRouterFree {
  readonly registry: ModelRegistry;
  readonly cache: CacheManager;
  readonly config: ConfigLoader;
  readonly capabilities: CapabilityDetector;
  readonly health: HealthChecker;
  readonly provider: ProviderAdapter;
  readonly router: FallbackRouter;
  readonly aliases: AliasManager;

  private _models: Model[] | null = null;

  constructor() {
    this.config = new ConfigLoader();
    this.cache = new CacheManager();
    this.registry = new ModelRegistry(this.cache, this.config);
    this.capabilities = new CapabilityDetector();
    this.health = new HealthChecker(this.config);
    this.provider = new ProviderAdapter(this.config);
    this.router = new FallbackRouter(this.provider, this.health, this.config);
    this.aliases = new AliasManager();
  }

  /** Initialize: fetch models, populate cache, validate aliases. */
  async init(): Promise<this> {
    this._models = await this.registry.fetchAll();
    const stale = this.aliases.validateAgainst(this._models);
    if (stale.length) {
      console.warn(`⚠️  Removed stale aliases: ${stale.join(', ')}`);
    }
    return this;
  }

  /** Get all models (cached after init). */
  get models(): Model[] {
    if (!this._models) {
      throw new Error('Call init() before accessing models.');
    }
    return this._models;
  }

  /** Refresh the model list from the API. */
  async refresh(): Promise<Model[]> {
    this.cache.invalidate();
    this._models = await this.registry.fetchAll();
    return this._models;
  }

  /** List free models, optionally filtered. */
  listFree(filters?: {
    modality?: string;
    hasTools?: boolean;
    hasVision?: boolean;
    search?: string;
  }): Model[] {
    let models = this.registry.filterFree(this.models);

    if (filters?.modality) {
      models = this.registry.filterByModality(models, filters.modality);
    }
    if (filters?.hasTools) {
      models = this.registry.filterByParameter(models, 'tools');
    }
    if (filters?.hasVision) {
      models = this.registry.filterByParameter(models, 'vision');
    }
    if (filters?.search) {
      models = this.registry.search(models, filters.search);
    }

    return models;
  }

  /** Get a model by ID or alias. */
  resolveModel(id: string): Model | null {
    const found = this.models.find((m) => m.id === id);
    if (found) return found;

    const aliasTarget = this.aliases.resolve(id);
    if (aliasTarget) {
      return this.models.find((m) => m.id === aliasTarget) ?? null;
    }

    return null;
  }

  /** Send a chat message using a model or alias. */
  async chat(
    modelOrAlias: string,
    messages: ChatMessage[],
    options: {
      maxTokens?: number;
      temperature?: number;
      stream?: boolean;
      tools?: any[];
      toolChoice?: string;
    } = {},
  ): Promise<ProviderResult> {
    const resolved = this.aliases.expandSelector(modelOrAlias, this.models);
    const modelId = resolved ?? modelOrAlias;

    return this.provider.complete({
      model: modelId,
      messages,
      maxTokens: options.maxTokens,
      temperature: options.temperature,
      stream: options.stream,
      tools: options.tools,
      toolChoice: options.toolChoice,
    });
  }

  /** Health check one or all free models. */
  async checkHealth(modelId?: string): Promise<HealthResult | HealthResult[]> {
    if (modelId) {
      return this.health.ping(modelId);
    }
    const freeModels = this.listFree();
    return this.health.checkMany(freeModels);
  }
}

